from playwright.sync_api import sync_playwright
import base64,struct,array,wave,math
OUT=Path('/workspace/review-klang25');OUT.mkdir(exist_ok=True)
with sync_playwright() as w:
 b=w.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--autoplay-policy=no-user-gesture-required']);p=b.new_page(viewport={'width':1600,'height':1000});p.set_default_timeout(90000);errors=[];remote=[];p.on('pageerror',lambda e:errors.append(str(e)));p.on('request',lambda r:remote.append(r.url) if r.url.startswith('http') and '127.0.0.1' not in r.url else None);p.goto('http://127.0.0.1:8049/Tipp-Expedition-4.7-Waldatelier.html');p.locator('#btn-play').click();p.wait_for_function("A25.ctx?.state==='running'");p.wait_for_timeout(250);assert p.evaluate("A25.theme==='forest'")
 p.keyboard.press('F8');assert p.evaluate('a25Dialog.open&&paused');before=p.evaluate('JSON.stringify([G.pos,S.res,S.coins,S.inv])');p.keyboard.press('Tab');assert p.locator('#a25-music-volume').evaluate('(el)=>el===document.activeElement');p.keyboard.press('ArrowRight');assert p.evaluate('a25Settings().musicVolume')==.29;p.keyboard.press('Tab');p.keyboard.press('Space');assert p.evaluate('a25Settings().nature===false');p.keyboard.press('Space');assert p.evaluate('a25Settings().nature===true');assert p.evaluate('JSON.stringify([G.pos,S.res,S.coins,S.inv])')==before
