 p.evaluate("""window.savedSpeech25={ctor:SpeechSynthesisUtterance,get:speechSynthesis.getVoices.bind(speechSynthesis),speak:speechSynthesis.speak.bind(speechSynthesis),cancel:speechSynthesis.cancel.bind(speechSynthesis)};window.SpeechSynthesisUtterance=class{constructor(t){this.text=t}};speechSynthesis.getVoices=()=>[{voiceURI:'de-a',name:'Deutsch A',lang:'de-DE'},{voiceURI:'de-b',name:'Deutsch B',lang:'de-DE'},{voiceURI:'fr',name:'Français',lang:'fr-FR'}];Object.defineProperty(speechSynthesis,'speaking',{configurable:true,get:()=>!!window.testUtterance25});speechSynthesis.speak=u=>{window.testUtterance25=u;u.onstart?.()};speechSynthesis.cancel=()=>{};""")
 p.keyboard.press('F8');p.locator('#a25-voice').select_option('de-b');p.locator('#a25-rate').fill('105');p.locator('#a25-speech-volume').fill('70');p.locator('#a25-voice-test').click();assert p.evaluate("testUtterance25.voice.voiceURI==='de-b'&&testUtterance25.rate===1.05&&testUtterance25.volume===.7");assert p.evaluate('A25.duck');p.evaluate('testUtterance25.onend()');assert p.evaluate('!A25.duck');p.keyboard.press('Escape');p.evaluate('delete speechSynthesis.speaking;window.SpeechSynthesisUtterance=savedSpeech25.ctor;speechSynthesis.getVoices=savedSpeech25.get;speechSynthesis.speak=savedSpeech25.speak;speechSynthesis.cancel=savedSpeech25.cancel;save()')
 p.reload();p.locator('#btn-play').click();assert p.evaluate("a25Settings().voice==='de-b'&&a25Settings().speechRate===1.05&&a25Settings().speechVolume===.7&&a25Settings().musicVolume===.29")
 p.evaluate("enterDesert(true);G.storm=null;S.world.storms=[];a25Sync()");assert p.evaluate("A25.theme==='desert'");p.evaluate('sh21Start(false,true);a25Sync()');assert p.evaluate('A25.theme===null');p.evaluate("G.ship21=null;S.where='hoehle';a25Sync()");assert p.evaluate('A25.theme===null')
 # Render the actual composition into an OfflineAudioContext. Both themes must
 # contain audible, bounded signals; no external sample requests are involved.
 for theme in ['forest','desert']:
  encoded=p.evaluate("""async theme=>{const c=new OfflineAudioContext(2,22050*18,22050),g=a25Graph(c);g.music.gain.value=.28;g.nature.gain.value=.24;for(let k=0;k*(theme==='desert'?.66:.8)<17;k++)a25Phrase(c,g.music,theme,k,.05+k*(theme==='desert'?.66:.8));if(theme==='forest')for(let i=0;i<3;i++)a25Bird(c,g.nature,2+i*6,100+i);const r=await c.startRendering(),a=r.getChannelData(0),bytes=new Uint8Array(a.buffer);let s='';for(let j=0;j<bytes.length;j+=8192)s+=String.fromCharCode(...bytes.subarray(j,j+8192));return btoa(s)}""",theme)
  samples=array.array('f');samples.frombytes(base64.b64decode(encoded));peak=max(abs(v) for v in samples);rms=math.sqrt(sum(v*v for v in samples)/len(samples));assert .001<rms<.15 and peak<.9,(theme,peak,rms)
  with wave.open(str(OUT/(theme+'.wav')),'wb') as f:f.setnchannels(1);f.setsampwidth(2);f.setframerate(22050);f.writeframes(b''.join(struct.pack('<h',round(max(-1,min(1,v))*32767)) for v in samples))
  print(theme,'peak',round(peak,4),'rms',round(rms,4),flush=True)
 assert not errors,errors;assert not remote,remote
